() => {
  const raw = localStorage.getItem('analytics-store');
  const store = JSON.parse(raw);
  const ds = store.state.dataSources.find(d => d.id === 'ds_1786406744499');
  store.state.activeDataSourceId = 'ds_1786406744499';
  store.state.activeTableId = ds?.tables?.[0]?.id || null;
  localStorage.setItem('analytics-store', JSON.stringify(store));
  return { switched: store.state.activeDataSourceId, table: store.state.activeTableId, dsName: ds?.name };
}

() => {
  const inputs = Array.from(document.querySelectorAll('textarea, input[type="text"]'));
  return inputs.map(el => ({ tag: el.tagName, placeholder: (el.getAttribute('placeholder')||'').slice(0,30), value: el.value }));
}

() => {
  const input = document.querySelector('input[placeholder*="用自然语言提问"]');
  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  nativeSetter.call(input, '各客户类型的客户数是多少');
  input.dispatchEvent(new Event('input', { bubbles: true }));
  input.dispatchEvent(new Event('change', { bubbles: true }));
  return input.value;
}

