    84→export async function invalidateQueryCache(dataSourceId?: string): Promise<void> {
    85→  if (isRedisEnabled()) {
    86→    try {
    87→      await getStateStore().deleteByPrefix(dataSourceId ? `qc:${dataSourceId}::` : 'qc:');
    88→      await getStateStore().deleteByPrefix(dataSourceId ? `qcidx:${dataSourceId}::` : 'qcidx:');
    89→    } catch {
    90→      // 失效操作失败不阻断主流程
    91→    }
    92→    return;
    93→  }
    94→  if (!dataSourceId) {
    95→    cache.clear();
    96→    semanticIndex.clear();
    97→    return;
    98→  }
    99→  for (const k of cache.keys()) {
   100→    if (k.startsWith(`${dataSourceId}::`)) cache.delete(k);
   101→  }
   102→  for (const k of semanticIndex.keys()) {
   103→    if (k.startsWith(`${dataSourceId}::`)) semanticIndex.delete(k);
