   142→/** 简易余弦相似度；维度不一致返回 0 */
   143→function cosineSim(a: number[], b: number[]): number {
   144→  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length || a.length === 0) return 0;
   145→  let dot = 0;
   146→  let na = 0;
   147→  let nb = 0;
   148→  for (let i = 0; i < a.length; i++) {
   149→    dot += a[i] * b[i];
   150→    na += a[i] * a[i];
   151→    nb += b[i] * b[i];
   152→  }
   153→  if (na === 0 || nb === 0) return 0;
   154→  return dot / (Math.sqrt(na) * Math.sqrt(nb));
