   157→/** 问题 embedding（基于归一化文本，标点/大小写差异不产生额外向量）；不可用返回 null */
   158→async function embedQuestion(question: string): Promise<number[] | null> {
   159→  const norm = normalizeQuestion(question);
   160→  if (norm.length < SEMANTIC_MIN_QUESTION_LEN) return null;
