   170→async function readSemanticIndex(idxKey: string): Promise<SemanticIndexEntry[]> {
   171→  const now = Date.now();
   172→  const alive = (list: SemanticIndexEntry[]) =>
   173→    list.filter((e) => e && typeof e.key === 'string' && Array.isArray(e.vec) && now - Number(e.at || 0) <= CACHE_TTL_MS);
   174→  if (isRedisEnabled()) {
   175→    try {
   176→      const raw = await getStateStore().get(`qcidx:${idxKey}`);
   177→      if (!raw) return [];
   178→      const parsed = JSON.parse(raw);
   179→      return Array.isArray(parsed) ? alive(parsed) : [];
