   195→  const entry: SemanticIndexEntry = {
   196→    key,
   197→    question: String(question).slice(0, 200),
   198→    vec: vec.map((v) => Math.round(v * 1e4) / 1e4),
   199→    at: Date.now(),
   200→  };
   201→  const list = await readSemanticIndex(idxKey);
   202→  const next = [entry, ...list.filter((e) => e.key !== entry.key)].slice(0, SEMANTIC_INDEX_MAX);
   203→  if (isRedisEnabled()) {
   204→    try {
   205→      await getStateStore().setEx(`qcidx:${idxKey}`, JSON.stringify(next), Math.ceil(CACHE_TTL_MS / 1000));
   206→    } catch {
   207→      // 索引写失败静默忽略（fail-open）
   208→    }
   209→    return;
   210→  }
   211→  semanticIndex.set(idxKey, next);
   212→}
