   214→export interface SemanticCacheHit {
   215→  payload: any;
   216→  matchedQuestion: string;
   217→  similarity: number;
   218→}
   219→
   220→/**
   221→ * L2 语义缓存查询：问题 embedding 与同数据源（同模型变体）索引内最近邻相似度≥阈值，
   222→ * 且对应 L1 条目仍存在时才命中（索引可能因 TTL 不同步残留，以 L1 为最终事实源）。
   223→ */
   224→export async function getSemanticCachedQuery(
   225→  dataSourceId: string,
   226→  question: string,
   227→  variant = ''
   228→): Promise<SemanticCacheHit | null> {
   229→  const vec = await embedQuestion(question);
   230→  if (!vec) return null;
   231→  const entries = await readSemanticIndex(semanticIndexKey(dataSourceId, variant));
