   233→  for (const e of entries) {
   234→    const similarity = cosineSim(vec, e.vec);
   235→    if (!best || similarity > best.similarity) best = { e, similarity };
   236→  }
   237→  if (!best || best.similarity < semanticCacheThreshold()) return null;
   238→  const payload = await getCachedQuery(best.e.key);
   239→  if (!payload) return null; // L1 已过期/已失效：索引残留不命中
   240→  return { payload, matchedQuestion: best.e.question, similarity: best.similarity };
   241→}
